class Solution {
    public int[] sortEvenOdd(int[] nums){
        List<Integer> even=new ArrayList<>(),odd=new ArrayList<>();
        for(int i=0;i<nums.length;i++)(i%2==0?even:odd).add(nums[i]);
        Collections.sort(even);
        odd.sort(Collections.reverseOrder());
        int e=0,o=0;
        for(int i=0;i<nums.length;i++)nums[i]=i%2==0?even.get(e++):odd.get(o++);
        return nums;
    }
}

code.kotlin:
class Solution {
    fun sortEvenOdd(nums:IntArray):IntArray{
        val even=nums.filterIndexed{
            index,_->index%2==0
        }.sorted();
        val odd=nums.filterIndexed{
            index,_->index%2==1
        }.sortedDescending();
        var e=0;
        var o=0;
        for(i in nums.indices)nums[i]=if(i%2==0)even[e++]else odd[o++];
        return nums
    }
}

